package lang

import (
	"regexp"
	"sort"
	"strings"
)

// The runtime parts a program doesn't use are switched off at build time (plan Phase 13, "smaller output"): Blink on
// an Uno was 16 KB of flash and half the RAM, nearly all of it runtime the program never called (the app protocol,
// serial input, and the blink/pattern/melody effects of every output, which tick() reaches through a virtual call
// so the linker can't drop them by itself).
//
// The rule is "off only when provably unused": the generated files are scanned for the runtime calls the generator
// itself writes (mujard::serial_line, mujard::app_*, .blink(...), ...), and a feature is switched off only when no
// file calls it. The runtime leaves a switched-off part undefined, so a mistake here fails the build at link time
// instead of quietly losing a feature. Programs with hand-written C++ are never scanned (see Generate).

const runtimeConfigFile = "mujard_config.h"

type rtFeature struct {
	define string         // what mujard_config.h defines when the feature is unused
	uses   *regexp.Regexp // a call that means the program uses it
}

var rtFeatures = []rtFeature{
	{"MUJARD_NO_APP", regexp.MustCompile(`\bapp_[a-z_]+\s*\(|\bAppPlot\b`)},
	{"MUJARD_NO_SERIAL_IN", regexp.MustCompile(`\bserial_(?:line|want_lines|take_line|has_line)\s*\(`)},
	{"MUJARD_NO_BLINK", regexp.MustCompile(`(?:\.|->)\s*blink\s*\(`)},
	{"MUJARD_NO_PATTERN", regexp.MustCompile(`(?:\.|->)\s*pattern\s*\(`)},
	{"MUJARD_NO_MELODY", regexp.MustCompile(`(?:\.|->)\s*melody\s*\(`)},
	// tone() and melody() both play through the core's tone(); without either, its timer interrupt is never linked in
	// and stays free for a library that defines it too (NewPing's timers on AVR: found by TestEveryLibraryBuilds).
	{"MUJARD_NO_TONE", regexp.MustCompile(`(?:\.|->)\s*(?:tone|melody)\s*\(`)},
}

// runtimeConfig is mujard_config.h for these generated files (with no defines when the program uses every part).
func runtimeConfig(files map[string]string) string {
	names := make([]string, 0, len(files))
	for name := range files {
		// The runtime itself defines these parts; everything else (the program, the runtime libraries it uses) calls them.
		if name == "mujard_rt.h" || name == "mujard_rt.cpp" || name == runtimeConfigFile || !(strings.HasSuffix(name, ".cpp") ||
			strings.HasSuffix(name, ".h") || strings.HasSuffix(name, ".ino")) {
			continue
		}
		names = append(names, name)
	}
	sort.Strings(names)
	used := func(f rtFeature) bool {
		for _, n := range names {
			if f.uses.MatchString(files[n]) {
				return true
			}
		}
		return false
	}
	var off []string
	noApp := false
	for _, f := range rtFeatures {
		if used(f) {
			continue
		}
		if f.define == "MUJARD_NO_SERIAL_IN" && !noApp {
			continue // the app's messages arrive as serial input: it stays on while the app protocol does
		}
		if f.define == "MUJARD_NO_APP" {
			noApp = true
		}
		off = append(off, f.define)
	}
	return runtimeConfigHeader(off)
}

// runtimeConfigHeader is mujard_config.h switching off these parts (none: the whole runtime).
func runtimeConfigHeader(off []string) string {
	var b strings.Builder
	b.WriteString("// Generated by Mujard - the runtime parts this program doesn't use, switched off so they take no flash or RAM.\n")
	b.WriteString("// Only ever \"off\": a part the program used would fail the build, never go missing quietly.\n")
	b.WriteString("#pragma once\n")
	for _, d := range off {
		b.WriteString("#define " + d + "\n")
	}
	if len(off) == 0 {
		b.WriteString("// (nothing switched off: this program keeps the whole runtime)\n")
	}
	return b.String()
}
